            books.Sort((a, b) => DateTime.Compare(a.PublicationDate, b.PublicationDate));

            // Output sorted books
            foreach (Book book in books)
            {
                Console.WriteLine("{0} - {1}", book.Title, book.PublicationDate);
            }
        }

        static List<Book> ReadBooksFromFile(string filePath)
        {
            List<Book> books = new List<Book>();

