```python
def find_words(matrix, words):
    found_words = []
    row_length = len(matrix[0])

    def search_words(x, y, word):
        if word == "":
            found_words.append(("".join(row) for row in matrix[x:x+word_height][y:y+word_width]))
            return True
        for I in range(x, row_length - word_width + 1):
            for j in range(y, row_length - len(word) + 1):
                if all(matrix[i+k][j+l] == word[k] for k in range(len(word)) for l in range(len(word[k]))):
                    word_matrix = [row[:] for row in matrix[i:i+len(word[0])] ]
                    for k in range(len(word)):
                        for l in range(len(word[k])):
                            word_matrix[k][l] = word[k][l]
                    if search_words(i, j, word[1:]):
                        found_words.append(word_matrix)
                        return True
        return False

    for word in words:
        word_height, word_width = len(word), max(map(len, word))
        if all(all(c.isalpha() for c in row) and all(c.islower() for c in row) for row in matrix) and \
           all(all(c.isalpha() for c in word_i) and all(c.islower() for c in word_i) for word_i in zip(*word)):
            if search_words(0, 0, word):
                break
    return found_words
