// Función para generar una pregunta con un número aleatorio entre 1 y 99
function generateMathQuestion() {
  const num1 = Math.floor(Math.random() * 99) + 1; // Número entre 1 y 99
  const num2 = Math.floor(Math.random() * 99) + 1; // Número entre 1 y 99
  const operations = ["+", "-"];

  const operator = operations[Math.floor(Math.random() * operations.length)];

  let question = `${num1} ${operator} ${num2}`;

  // Reordena los operandos para que al menos aparezcan tres dígitos en el resultado
  if (operator === "+") {
    while (question.length < 4) {
      question = `${question}${Math.floor(Math.random() * 10)}`;
    }
  } else {
    const diff = Math.abs(num1 - num2);
    while (diff.toString().length < 4) {
      diff *= 10;
    }
    question = `${num1} ${operator} ${diff}`;
  }

  return question;
}

// Función para verificar la respuesta del usuario y devolver el resultado del cálculo
function checkAnswer(userAnswer, question) {
  const operator = question.substring(question.indexOf(" ") + 1, question.indexOf(" ", question.indexOf(" ") + 1));
  const num1 = parseInt(question.substring(0, question.indexOf(" ")));
  const num2 = parseInt(question.substring(question.indexOf(" ") + 2));

  let result;

  if (operator === "+") {
    result = num1 + num2;
  } else if (operator === "-") {
    result = num1 - num2;
  }

  return result === parseInt(userAnswer) ? true : false;
}

// Función para jugar el juego y contabilizar los puntos
function playGame() {
  let score = 0;

  while (true) {
    const question = generateMathQuestion();
    console.log(`Pregunta: ${question}`);

    const userInput = prompt("Respuesta:");

    if (checkAnswer(userInput, question)) {
      score++;
      console.log(`¡Respondiste correctamente! Tu puntuación actual: ${score}`);
    } else {
      console.log("Lo siento, la respuesta es incorrecta.");
    }

    // Si el usuario desea abandonar el juego, se detiene el bucle infinito
    if (confirm("¿Quieres seguir jugando?")) continue;
    break;
  }

  console.log(`¡Gracias por jugar! Tu puntuación final es: ${score}`);
}

// Inicio del juego
playGame();
```

