    } else {
      alert(`Sorry, the correct answer is ${eval(question)}`);
    }

    startGame(); // Generar una nueva pregunta
  });

  answerContainer.appendChild(submitButton);
}

function generateMathQuestion() {
  const minNumber = 1;
  const maxNumber = 20;
  const operation = generateRandomOperation();

  let question;
  let answer;

  if (operation === '+') {
    const num1 = generateRandomNumber(minNumber, maxNumber);
    const num2 = generateRandomNumber(minNumber, maxNumber);
    question = `${num1} ${operation} ${num2}`;
    answer = num1 + num2;
  } else if (operation === '-') {
    const num1 = generateRandomNumber(minNumber, maxNumber);
    const num2 = generateRandomNumber(minNumber, maxNumber);
    if (num1 < num2) {
      const temp = num1;
      num1 = num2;
      num2 = temp;
    }
    question = `${num1} ${operation} ${num2}`;
    answer = num1 - num2;
  }

  return question;
}

startGame(); // Inicia el juego
