```javascript
// Constantes para el juego
const DIFFICULTY_LEVELS = {
  EASY: {
    min: 1,
    max: 10,
  },
  MEDIUM: {
    min: 11,
    max: 50,
  },
  HARD: {
    min: 51,
    max: 100,
  },
};
const DEFAULT_DIFFICULTY = 'EASY';

// Funciones para el juego
function generateRandomNumberInRange(level) {
  return Math.floor(Math.random() * (level.max - level.min + 1)) + level.min;
}

function generateMathProblem(level) {
  const operator = Math.random() < 0.5 ? '+' : '-';
  const a = generateRandomNumberInRange(level);
  const b = generateRandomNumberInRange(level);
  let result;
  if (operator === '+') {
    result = a + b;
  } else {
    result = a - b;
  }
  return {
    question: `${a} ${operator} ${b}`,
    answer: result,
  };
}

function checkAnswer(answer, expectedAnswer) {
  return answer === expectedAnswer;
}

// Variables para el juego
let points = 0;
let difficulty = DEFAULT_DIFFICULTY;
let questionElement = document.querySelector('#question');
let answerElement = document.querySelector('#answer');
let resultElement = document.querySelector('#result');

// Event listener para enviar la respuesta del acertijo
function submitHandler(event) {
  event.preventDefault();
  const userAnswer = Number(answerElement.value);
  const mathProblem = generateMathProblem(DIFFICULTY_LEVELS[difficulty]);
  questionElement.textContent = mathProblem.question;
  answerElement.value = '';
  if (checkAnswer(userAnswer, mathProblem.answer)) {
    // Respuesta correcta, puntos++
    points++;
    resultElement.textContent = `¡Respuesta correcta! Puntos: ${points}`;
  } else {
    // Respuesta incorrecta, mostrar solución
    resultElement.textContent = `Respuesta incorrecta. La solución es: ${mathProblem.answer}`;
  }
}

// Inicializar el juego
