  // Selecionar el nivel de dificultad por defecto
  const difficultySelectElement = document.querySelector('#difficulty-select');
  Array.from(difficultySelectElement.options)
    .filter(option => option.value)
    .forEach(option => option.selected = option.value === DEFAULT_DIFFICULTY);

