```javascript
// Función para generar preguntas aleatorias con sumas y restas de dos números entre 1 y 10
function generarPregunta() {
  const primerNumero = Math.floor(Math.random() * 10) + 1;
  const segundoNumero = Math.floor(Math.random() * 10) + 1;
  const operadores = ["+", "-"];
  const operadorAleatorio = operadores[Math.floor(Math.random() * operadores.length)];
  const resultado = eval(`${primerNumero} ${operadorAleatorio} ${segundoNumero}`);

  const pregunta = `${primerNumero} ${operadorAleatorio} ${segundoNumero} = ?`;

  return { pregunta, resultado };
}

// Función para comparar la respuesta dada con el resultado esperado
function comprobarRespuesta(pregunta, respuestaUsuario) {
  if (parseInt(respuestaUsuario) === pregunta.resultado) {
    return true;
  }
  return false;
}

// Función para un ciclo de juego que pida el nombre del jugador y permita jugar tantas veces como el usuario desee
function juego() {
  let puntos = 0;
  console.log("Bienvenido al juego de acertijos matemáticos!");

  const nombreUsuario = prompt("Por favor, introduce tu nombre:");

  do {
    const pregunta = generarPregunta();
    const preguntaTexto = `${pregunta.pregunta}`;

    const respuestaUsuario = prompt(`${nombreUsuario}, ${preguntaTexto}`);

    if (comprobarRespuesta(pregunta, respuestaUsuario)) {
      puntos++;
      console.log(`¡Respuesta correcta! Puntos: ${puntos}`);
    } else {
      console.log(`Respuesta incorrecta. La respuesta correcta era: ${pregunta.resultado}`);
    }
  } while (confirm(`¡${nombreUsuario}! ¿Quieres jugar una pregunta más?`));

  console.log(`¡Gracias por jugar, ${nombreUsuario}! Tu puntuación final es de ${puntos} puntos.`);
}

juego();
```

