function generateMathProblem() {
  // Generamos dos números aleatorios entre 1 y 20 (inclusive)
  const num1 = Math.floor(Math.random() * 20) + 1;
  const num2 = Math.floor(Math.random() * 20) + 1;

  // Elijemos aleatoriamente entre suma y resta
  const operator = Math.floor(Math.random() * 2);
  let problem;

  if (operator === 0) {
    problem = `${num1} + ${num2} =`;
  } else {
    problem = `${num1} - ${num2} =`;
  }

  return { problem, answer: (operator === 0 ? num1 + num2 : num1 - num2) };
}
