function playMathGame() {
  let score = 0;

  while (true) {
    const problem = generateMathProblem();

    console.log(problem.problem);

    const userAnswer = parseInt(prompt("Introduzca la respuesta"));

    if (userAnswer === problem.answer) {
      score++;
      console.log(`¡Respuesta correcta! Tu puntuación actual es ${score}.`);
    } else {
      console.log(`Respuesta incorrecta. La respuesta correcta era ${problem.answer}.`);
      break;
