//Implementación ejemplar para generar actividad que cumple con al menos una habilidad entre las listadas de múltiples inteligencias
Activity GenerateActivityWithNeededSkills(List<Activity> activities, List<MultipleIntelligence> multipleIntelligence)
{
    foreach (var activity in activities)
    {
        bool containsRequiredSkills = true;
        foreach (var skill in multipleIntelligence)
        {
            containsRequiredSkills = containsRequiredSkills && (activity.RequiredSkills.Contains(skill));
            if (!containsRequiredSkills)
            {
                break;
            }
        }

        if (containsRequiredSkills)
        {
            return activity;
        }
    }

    throw new Exception("No se encontró actividad con habilidades de múltiples inteligencias necesarias");
}

//Implementación ejemplar para generar ubicación geográfica cercana a una selección
Location GenerateCloselyLocatedLocation(List<Location> locations, Location currentLocation)
{
    double minDistance = double.MaxValue;
    Location closestLocation = null;

    foreach (var location in locations)
    {
        double distance = Math.Sqrt(Math.Pow(currentLocation.Longitud - location.Longitud, 2) + Math.Pow(currentLocation.Latitud - location.Latitud, 2));
        if (distance < minDistance)
        {
            minDistance = distance;
            closestLocation = location;
        }
    }

    return closestLocation;
}

