    // Cargar las actividades por inteligencia múltiple desde un archivo de texto
    static List<Activity> LoadActivitiesFromFile(string fileName)
    {
        List<Activity> activities = new List<Activity>();

        try
        {
            using (StreamReader reader = new StreamReader(fileName))
            {
                string line;
                while ((line = reader.ReadLine()) != null)
                {
