                    string name = parts[0];
                    IntelligenceType intelligenceType = (IntelligenceType)Enum.Parse(typeof(IntelligenceType), parts[1]);
                    activities.Add(new Activity { Name = name, IntelligenceType = intelligenceType.ToString() });
