                    string[] parts = line.Split(',');
                    foreach (var part in parts)
                    {
                        string[] activityParts = part.Split('-');
                        Activity activity = new Activity { Name = activityParts[0], Season = (SeasonType)Enum.Parse(typeof(SeasonType), activityParts[1]) };
                        seasonActivities.Add(activity);
                    }
                    seasonalActivities.Add(seasonActivities);
                }
            }
