        List<Activity> uniqueIntelligencesActivities = GetUniqueActivitiesByIntelligenceType(activities);

        // Obtener la lista de actividades por temporada utilizando una matriz para asignar las actividades por temporada
        int daysPerSeason = daysToPlan / 4;
        List<List<Activity>> seasonalItinerary = new List<List<Activity>>();
        for (int I = 0; I < SeasonType.Spring; I++) // Inicializar con espacios vacíos
