            seasonalItinerary[(int)seasonalIndex].Add(GetRandomActivityFromSeasonalList(activities, seasonalActivities[(int)seasonalIndex]));
        }

        // Fusionar las listas temporada por temporada para crear el itinerario final
        List<Activity> itinerary = new List<Activity>();
        for (int I = 0; I < SeasonType.Spring; i++)
