    public List<DailyItinerary> GenerateTour()
    {
        // Separar las actividades por inteligencia múltiple y estación
        Dictionary<MultiIntelligence, Dictionary<Season, List<LondonActivity>>> ActivitiesByMISeason =
            AllActivities.GroupBy(activity => activity.RequiredMI)
                         .ToDictionary(group => group.Key,
                                       group => group.GroupBy(activity => activity.Season)
                                                    .ToDictionary(seasonGroup => seasonGroup.Key, seasonGroup => seasonGroup.ToList()));

        // Generar itinerario para cada día disponible
        List<DailyItinerary> DailyItineraries = new List<DailyItinerary>(DaysAvailable);

        for (int day = 1; day <= DaysAvailable; day++)
        {
