        }

        // Agregar actividades con restricciones de días específicos (si hay)
        if (SpecificDays.Any())
        {
            foreach (int day in SpecificDays)
            {
                DailyItineraries[day - 1].Activities.AddRange(
                    AllActivities.Where(activity => activity.Name.Contains($"Day{day}")).ToList()
                );
            }
        }

        // Agregar actividades no restringidas por día
        List<Dictionary<MultiIntelligence, List<LondonActivity>>> RemainingActivities =
            TourGenerator.PopulateRemainingActivities(DailyItineraries, ActiviesByMISeason);

        // Generar secuencia de actividades por día
        List<List<int>> OptimalTourSequence = new List<List<int>>();
        for (int day = 0; day < DailyItineraries.Count; day++)
        {
