        }

        // Combinar las secuencias diarias en un itinerario por cada día
        List<DailyItinerary> FinalTour = new List<DailyItinerary>();
        for (int day = 0; day < DailyItineraries.Count; day++)
        {
            DailyItineraries[day].Activities.Clear();

            for (int activityIndex = 0; activityIndex < OptimalTourSequence[day].Count; activityIndex++)
            {
                int activityId = OptimalTourSequence[day][activityIndex];
                LondonActivity activity = AllActivities[activityId];
                DailyItineraries[day].Activities.Add(activity);
            }

            FinalTour.Add(DailyItineraries[day]);
        }

