    private static List<Dictionary<MultiIntelligence, List<LondonActivity>>> PopulateRemainingActivities(List<DailyItinerary> dailyItineraries,
                                                                                                            Dictionary<MultiIntelligence, 
                                                                                                            Dictionary<Season, List<LondonActivity>>> activitiesByMISeason)
    {
        List<Dictionary<MultiIntelligence, List<LondonActivity>>> RemainingActivities = 
