        foreach (DailyItinerary dailyItinerary in dailyItineraries)
        {
            Dictionary<MultiIntelligence, List<LondonActivity>> RemainingMIActivities =
                new Dictionary<MultiIntelligence, List<LondonActivity>>();

            foreach (MultiIntelligence mi in activitiesByMISeason.Keys)
            {
                RemainingMIActivities.Add(mi, activitiesByMISeason[mi].Values.ToList()[0].ToList());
            }

            RemainingActivities.Add(RemainingMIActivities);
        }

        return RemainingActivities;
    }

    private static List<int> FindOptimalTourSequence(
        Dictionary<MultiIntelligence, List<LondonActivity>> activitiesByMI, 
        int numOfActivities, int maxDuration)
    {
        List<int> tourSequence = new List<int>();
        List<List<LondonActivity>> activitiesGroupsByMI = new List<List<LondonActivity>>();
        double optimalTourCost = Double.PositiveInfinity;

        // Separar actividades por inteligencia múltiple
        foreach (KeyValuePair<MultiIntelligence, List<LondonActivity>> miActivity in activitiesByMI)
        {
            activitiesGroupsByMI.Add(miActivity.Value.ToList());
        }

        // Generar todas las secuencias posibles para cada grupo de actividades
        List<List<List<int>>> allTourSequencesByMI = new List<List<List<int>>>();
        for (int I = 0; I < activitiesGroupsByMI.Count; i++)
        {
            List<List<int>> tourSequences = TourGenerator.GenerateAllTourSequences(activitiesGroupsByMI[i], numOfActivities);
            allTourSequencesByMI.Add(tourSequences);
        }

        // Calcular costo (distancia) de cada secuencia posiblemente válida
        foreach (List<int> sequenceGroup in GetAllCartesianProducts(allTourSequencesByMI))
        {
            double tourCost = TourGenerator.CalculateTourCost(sequenceGroup, maxDuration);
            if (tourCost < optimalTourCost && sequenceGroup.Count == numOfActivities)
            {
                optimalTourCost = tourCost;
                tourSequence = sequenceGroup.ToList();
            }
        }

        return tourSequence;
    }

    private static List<List<List<int>>> GetAllCartesianProducts(List<List<List<int>>> inputLists)
    {
        if (inputLists.Count == 0)
        {
            return new List<List<List<int>>>() { new List<List<int>> { new List<int>() } };
        }

        List<List<List<int>>> results = new List<List<List<int>>>();
        List<List<int>> currentlyProcessedList = new List<List<int>>();
        currentlyProcessedList.Add(new List<int>());

        foreach (List<List<int>> list in inputLists)
        {
            List<List<List<int>>> newResults = new List<List<List<int>>>();

            foreach (List<int> combination in GetAllCartesianProducts(currentlyProcessedList, list))
            {
                newResults.Add(combination.Concat(currentlyProcessedList).ToList());
            }

            results.AddRange(newResults);
            currentlyProcessedList.Clear();
        }

        return results.Where(list => list.Count == inputLists.Count).ToList();
    }

    private static List<List<int>> GenerateAllTourSequences(List<LondonActivity> activities, int numOfActivities)
    {
        List<List<List<int>>> allSequences = new List<List<List<int>>>();
        int length = 2;

        while (true)
        {
            List<List<int>> currentLevelSequences = TourGenerator.GenerateAllSequences(activities, length);
            allSequences.Add(currentLevelSequences);

            if (currentLevelSequences.Count >= Math.Pow(activities.Count, length) / (numOfActivities + 1))
            {
                break;
            }

            length++;
        }

        List<List<int>> filteredSequences = new List<List<int>>();
        foreach (List<List<int>> levelSequences in allSequences)
        {
            filteredSequences.AddRange(levelSequences.Where(sequence => sequence.Count == numOfActivities).ToList());
        }

        return filteredSequences;
    }

    private static List<List<int>> GenerateAllSequences(List<LondonActivity> activities, int sequenceLength)
    {
        List<List<int>> sequences = new List<List<int>>();
        List<int> currentSequence = new List<int>();

        if (sequenceLength == 1)
        {
            foreach (int I in Enumerable.Range(0, activities.Count))
            {
                List<int> sequence = currentSequence.ToList();
                sequence.Add(i);
                sequences.Add(sequence);
            }

            return sequences;
        }

        foreach (int I in Enumerable.Range(0, activities.Count))
        {
            List<int> sequence = currentSequence.ToList();
            sequence.Add(i);
            sequences.AddRange(TourGenerator.GenerateAllSequences(activities, sequence, sequenceLength));
        }

        return sequences.Distinct(new List<int>()).ToList();

        List<List<int>> GenerateAllSequences(List<LondonActivity> activities, List<int> sequence, int sequenceLength)
        {
            if (sequenceLength == 1)
            {
               sequences.Add(sequence);
                return;
            }

            for (int I = 0; I < activities.Count; i++)
            {
                if (!sequence.Contains(i))
                {
                    List<int> newSequence = sequence.ToList();
                    newSequence.Add(i);
                    GenerateAllSequences(activities, newSequence, sequenceLength - 1);
                }
            }
        }
    }

    private static double CalculateTourCost(List<int> tourSequence, int maxDuration)
    {
        double tourCost = 0;

        for (int I = 0; I < tourSequence.Count - 1; i++)
        {
            LondonActivity activityA = AllActivities[tourSequence[i]];
            LondonActivity activityB = AllActivities[tourSequence[i + 1]];

            // Implementar función de coste que considere distancias, transporte público, etc.
            double distanceCost = Math.Sqrt(Math.Pow(activityA.Season - activityB.Season, 2) + Math.Pow(activityA.RequiredMI - activityB.RequiredMI, 2));

            tourCost += distanceCost;
        }

        return tourCost <= maxDuration ? tourCost : Double.PositiveInfinity;
    }
}
