public static async Task<List<Location>> GetSuggestions(string apiKey, string location, string language)
{
    using HttpClient client = new HttpClient();

    string baseUri = "https://api.tripadvisor.com/api/2/attractions/search?";
    string parameters = $"loc={location}&lang={language}&sort=popularity&apiKey={apiKey}";

    string requestUri = baseUri + parameters;

