   public static IEnumerable<Activity> CreateOptimizedRoute(IEnumerable<Activity> activities)
   {
       // Convertir las actividades a puntos geográficos.
       var points = activities.Select(a => new PointF((float) a.Longitude, (float) a.Latitude));

       // Implementación simplificada del algoritmo de Pareto (no toma en cuenta la variedad de inteligencias múltiples).
       var paretoOptimalPoints = new List<PointF>();

       int n = points.Count;
       double[,] distances = new double[n, n];

       // Calcula las distancias entre todos los puntos.
       for (int I = 0; I < n; i++)
       {
           for (int j = i + 1; j < n; j++)
           {
               PointF p1 = points[i];
               PointF p2 = points[j];
               double dist = Math.Sqrt(Math.Pow(p1.X - p2.X, 2) + Math.Pow(p1.Y - p2.Y, 2));
               distances[i, j] = distances[j, i] = dist;
           }
       }

       // Define el problema de ruta con múltiples objetivos.
       var problem = new MultiObjectiveTspProblem(points);

       // Optimiza las rutas para minimizar la distancia total y maximizar la diversidad de las inteligencias múltiples.
       var solutions = MultiObjectiveOptimization.GetParetoFrontiers(problem, t =>
       {
           var routeDistance = problem.CalculateTotalDistance(t);
           var uniqueIntelligences = t.GroupBy(p => p.IntelligenceMultiple)
               .Select(g => g.Count())
               .Distinct()
               .Count();

           return new double[] { routeDistance, -uniqueIntelligences };
       }).OrderByDescending(s => s[0]);

       // Selecciona la solución que cumple con el requisito de las 16 inteligencias múltiples.
       var optimizedRoute = solutions.First(s => s.Count() == 16);

       // Convierte los puntos optimizados en actividades.
       var optimizedActivities = optimizedRoute.Select(p => activities.Single(a => a.Latitude == p.Y && a.Longitude == p.X));

       return optimizedActivities;
   }
   ```

