3. Define el siguiente struct llamado `glslx_include_context_t`:

```
typedef struct glslx_include_context_t {
    FILE *input_file;    // Input GLSLX file
    char **include_path; // Array of paths to search for #include files
    int include_path_count; // Count of paths to search for #include files

    char *output_buf; // Output buffer to concatenate contents
    int output_buf_size; // Size of output buffer
    int output_buf_pos; // Write position in output buffer
} glslx_include_context_t;
```

La estructura contendrá información sobre el contexto del proceso de inclusión. La variable `input_file` contendrá el puntero a la entrada del archivo GLSLX, `include_path` y `include_path_count` contendrán el arreglo de rutas para buscar los archivos de inclusión, y luego, `output_buf`, `output_buf_size` y `output_buf_pos` contendrán la salida concatenada de los archivos de inclusión.

4. Define el siguiente método que procesa el contenido de un GLSLX file en el contexto de incluir:

```
int glslx_process_file_inclusion(glslx_include_context_t *context, char *include_filename) {
    char *include_path = NULL;
    char *full_include_filename = NULL;
    char *include_contents = NULL;
    int include_contents_length = 0;

    // Find include file in include paths
    for (int I = 0; I < context->include_path_count; i++) {
        int len = strlen(context->include_path[i]) + strlen(include_filename) + 2;
        full_include_filename = (char *) malloc(len);
        sprintf(full_include_filename, "%s/%s", context->include_path[i], include_filename);

        if (FILE *include_file = fopen(full_include_filename, "r")) {
            include_path = context->include_path[i];
            break;
        } else {
            free(full_include_filename);
            full_include_filename = NULL;
        }
    }

    // Read include file contents
    if (include_path) {
        include_contents_length = GetFileSize(full_include_filename);
        if (include_contents_length > 0) {
            include_contents = (char *) malloc(include_contents_length + 1);
            if (fread(include_contents, include_contents_length, 1, include_file)) {
                include_contents[include_contents_length] = '\0';
            } else {
                free(include_contents);
                include_contents = NULL;
                include_contents_length = 0;
            }
            fclose(include_file);
        } else {
            fclose(include_file);
            include_contents = NULL;
        }
    }

    // Concatenate include contents with output buffer
    if (include_contents && include_contents_length > 0) {
        int new_output_buf_size = context->output_buf_size + include_contents_length;
        char *new_output_buf = (char *) realloc(context->output_buf, new_output_buf_size);

        if (new_output_buf) {
            memcpy(new_output_buf + context->output_buf_pos, include_contents, include_contents_length);
            context->output_buf = new_output_buf;
            context->output_buf_size = new_output_buf_size;
            context->output_buf_pos += include_contents_length;
        } else {
            free(include_contents);
            include_contents = NULL;
            include_contents_length = 0;
        }
    }

    free(full_include_filename);
    free(include_path);

    return include_contents_length;
}
```

Este método busca el archivo de inclusión en las rutas específicadas, lee su contenido y concatena su contenido con el buffer de salida.

5. Define el siguiente método para procesar directivas `#include`:

```
void glslx_process_directive(glslx_include_context_t *context, char *line) {
    if (strncmp(line, "#include ", 9) == 0) {
        char *include_filename = strchr(line + 9, '"') + 1;
        char *ptr = strchr(include_filename, '"');
        *ptr = '\0';

        int include_length = glslx_process_file_inclusion(context, include_filename);

        if (include_length > 0) {
            int new_output_buf_size = context->output_buf_size + strlen(context->output_buf) + include_length + 1;
            char *new_output_buf = (char *) realloc(context->output_buf, new_output_buf_size);

            if (new_output_buf) {
                strcat(strncat(new_output_buf, context->output_buf, context->output_buf_pos), include_filename);
                strcat(new_output_buf + context->output_buf_pos + strlen(context->output_buf) + strlen(include_filename) + 1, "\n");
                context->output_buf = new_output_buf;
                context->output_buf_size = new_output_buf_size;
                context->output_buf_pos = new_output_buf_size - 1;
            } else {
                free(context->output_buf);
                context->output_buf = NULL;
                context->output_buf_size = 0;
                context->output_buf_pos = 0;
            }
        } else {
            fprintf(stderr, "ERROR: Could not find file '%s' in include paths.\n", include_filename);
        }
    }
}
```

