```csharp
using System.Collections.Generic;
using UnityEngine;

namespace YourModName
{
    public class FlyingPlayerController : ACharacter
    {
        public float flySpeed = 50.0f;
        public float flyUpwardSpeed = 100.0f;

        private bool isFlying = false;
        private float flyInputAxis = 0.0f;
        private float flyDirAxis = 0.0f;

        protected override void MovedUpdates()
        {
            base.MovedUpdates();

            // Handle the flying control
            if (isFlying)
            {
                AddMovementInput(FVector2(flyInputAxis, flyDirAxis));

                // Fly upward
                AddMovementInput(FVector2(0, flyUpwardSpeed));
            }
        }

        private void StartFlying()
        {
            AddMovementInput(FVector2(flyInputAxis, flyDirAxis));
            isFlying = true;
        }

        private void StopFlying()
        {
            SetMovementMode(MOVEMENT_MODE_GROUND);
            isFlying = false;
        }

        public override void SetupPlayerInputComponent(PlayerInputComponent playerInputComponent)
        {
            base.SetupPlayerInputComponent(playerInputComponent);

            playerInputComponent.BindAction("StartFlying", new InputAction("Gameplay", "StartFlying", true, TriggerButton));
            playerInputComponent.BindAction("StopFlying", new InputAction("Gameplay", "StopFlying", true, TriggerButton));
            playerInputComponent.BindAxis("FlyInputAxis", new InputAxis("Gameplay", "FlyInputAxis", InputActionType.Value, 0, 1, InputQueryParam.Absolute));
            playerInputComponent.BindAxis("FlyDirAxis", new InputAxis("Gameplay", "FlyDirAxis", InputActionType.Value, 0, 1, InputQueryParam.Absolute));
        }

        private void OnStartFlying(InputAction action, float value, bool bPerformingMovement)
        {
            if (PlayerCharacterMovement.IsFalling() && !PlayerCharacterMovement.IsFallingOffStairs())
            {
                StartFlying();
            }
        }

        private void OnStopFlying(InputAction action, float value, bool bPerformingMovement)
        {
            StopFlying();
        }

        private void OnFlyInputAxis(InputAction action, float value)
        {
            flyInputAxis = value;
        }

        private void OnFlyDirAxis(InputAction action, float value)
        {
            flyDirAxis = value;
        }
    }
}
```

