```csharp
using System;
using UnityEngine;
using OpenKit.SDK.Interface;
using OpenKit.SDK.ConanSharedTypes;
using ConanExiles.ZNet;

namespace YourModNamespace
{
    public class FlyHarness : BatesModUtil.ModInitializable
    {
        public override void Initialize()
        {
            ZNetEvtHandlers.RegisterHackHook(InitHack, HackPhase.PreProcess, "FlyHarness_InitHack");
            ZNetEvtHandlers.RegisterEventHook(OnPlayerSpawned, ZNetEvents.Player.Spawned);
        }

        private void InitHack()
        {
            ItemBlueprint blueprint = ItemBlueprint.Create();
            blueprint.ItemID = "YourFlyHarnessID";
            blueprint.DisplayNameLocKey = "YourDisplayName";
            blueprint.Tooltip = "YourToolip";
            blueprint.ClassName = "FlyHarness";
            blueprint.Side = ItemSide.All;
            blueprint.Tags.Add("PlayerEquipment");
            blueprint.Tags.Add("Hull");
            blueprint.Tags.Add("FlyHarness");

            blueprint.InitVFXEnabled = false;
            blueprint.InitSoundEnabled = false;

            blueprint.SetInventoryIcon("YourFlyHarnessIcon", "YourFlyHarnessIconInfo");
            blueprint.SetPortraitIcon("YourFlyHarnessPortrait");

            ConanAggBlueprints.Instance.Register(blueprint);

            WeaponBlueprint weaponBlueprint = WeaponBlueprint.Create();
            weaponBlueprint.ClassName = "Weapon_FlyHarness";
            weaponBlueprint.ItemsToSpawn.Add(blueprint.ItemID);

            ItemBlueprint.ItemEquipContext context = new ItemBlueprint.ItemEquipContext();
            context.Weapon = weaponBlueprint;

            blueprint.EquipContext = context;

            ZNetSceneObject.CreateSceneObject(blueprint.ClassName, blueprint.ItemID);
        }

        private void OnPlayerSpawned(ZNetEvt_PlayerSpawnedEventArgs args)
        {
            if (args.IsLocal)
            {
                var playerItemInstance = ConanManager.GetItemInstance(args.PlayerIdentity);
                if (playerItemInstance != null)
                {
                    var flyHarnessItemInstance = playerItemInstance.FindItemInstance("YourFlyHarnessID");
                    if (flyHarnessItemInstance != null)
                    {
                        flyHarnessItemInstance.Equip();
                    }
                }
            }
        }
    }
}
```

