    url = "https://github.com/your-username/mod-fly-harness"
    description = "Fly Harness mod for Conan Exiles"
    settings = "os"
    generators = "cmake"

    def source(self):
        self.run("cd source && python build.py")

    def build(self):
        self.run("cd source && cmake . -DBUILD_SHARED_LIBS=OFF -DBUILD_STATIC_LIBS=ON")
        self.run("cd source && cmake --build . --config Release --target ConanExiles_Mod")

        self.copy("FlyHarness.cs", dst="Assets/Scripts", src="source")
        self.copy("*.dll", dst="bin", keep_path=False)
        self.copy("*.pdb", dst="bin", keep_path=False)

    def package_info(self):
        self.cpp_info.libs.append("ConanServer")
        self.cpp_info.libs.append("ConanDev")

    def package_info(self):
        self.cpp_info.libs.append("ConanServer")
        self.cpp_info.libs.append("ConanDev")

        if self.settings.os == "Windows":
            self.copy("FlyHarness.dll", dst="bin", src="source/ConanExiles_Mod/Release")

    def deploy(self):
        self.copy("*.dll", dst="bin", keep_path=False)
        self.copy("*.pdb", dst="bin", keep_path=False)
        self.copy("FlyHarness.dll", dst="bin", src=".", keep_path=False)

        self.copy("FlyHarness.cs", dst="Assets/Scripts", src=".", keep_path=True)

        if self.context != "edit":
            self.copy("*.meta", dst="Assets", keep_path=False)
            # this is to include the package as a module
            self.copy("*.manifest", dst="Assets", keep_path=False)
            self.copy("module.staging.targets.json", dst=".", keep_path=True)

            self.run('cd Assets && zip -r9 "../%(name)s.zip" *')

            if self.options.shared:
                self.copy("*.dll", dst="bin", keep_path=False)
            else:
                self.copy("*.dll", dst="bin", keep_path=False)
                self.copy("*.pdb", dst="bin", keep_path=False)
