```csharp
using System;
using Conduit;
using ConanExiles;
using Jimmylim98.Items.Cloth;
using Jimmylim98.Items.Cloth.Networking;
using Jimmylim98.Items.Cloth.Teleportation;
using Jimmylim98.Items.Cloth.Utilities;
using Jimmylim98.Items.Cloth.Weapons;
using JetBrains.Annotations;
using UnityEngine;
using UnityEngine.Networking;

public class FlyingClothItem : BaseItem
{
    private int jumpCount;
    private float nextJumpTime;
    private float maxJumpTime;
    private float jumpHeight;

    public override bool DoItempickup(Player player, int quantity)
    {
        player.AirControl = 1;
        player.UseJumpInputForMovement = false;
        player.AddSkill(GetSkillDefinition("FlyingCloth"), 1);

        jumpCount = 0;
        nextJumpTime = 0;
        maxJumpTime = 0;
        jumpHeight = 15;

        return base.DoItempickup(player, quantity);
    }

    private void Start()
    {
        var abilityPrefab = Resources.Load<Ability>("FlyingClothAbility");
        var abilityHandler = gameObject.AddComponent<ConanAbilitySystemHandler>();
        var ability = Object.Instantiate(abilityPrefab);

        ability.Cooldown = 3f;
        ability.Rank = 1;
        ability.TryProcessCooldown();
        abilityHandler.SetAbility(ability);

        var abilityInputBuilder = new AbilityInputBuilder(this);
        abilityInputBuilder.AddInput("Jump", new InputBind(KeyCode.Space));
        abilityHandler.AddInputBuilder(abilityInputBuilder);

        abilityHandler.InitializeAbilities();
    }

    private void Update()
    {
        if (!Physics.Raycast(transform.position, Vector3.down, out RaycastHit hit, 1.0f)) return;

        if (Time.time > nextJumpTime)
        {
            if (maxJumpTime == 0)
            {
                maxJumpTime = jumpHeight / Physics.gravity.y;
            }

            if (jumpCount < 2)
            {
                playercharacter.AddForce(new Vector3(0, jumpHeight, 0), ForceMode.Impulse);
                jumpCount++;
                nextJumpTime = Time.time + ability.Cooldown;
            }
        }
    }

    private void OnDestroy()
    {
        if (playercharacter)
        {
            playercharacter.AirControl = 0;
            playercharacter.UseJumpInputForMovement = true;
            player.RemoveSkill(GetSkillDefinition("FlyingCloth"));
        }
    }

    [ItemSkillDefinition("FlyingCloth", 1)]
    public ItemSkillDefinition FlyingClothSkill { get; private set; }

    private PlayerCharacter playercharacter =>
        GameObject.FindObjectOfType<PlayerCharacter>();

    private ItemSkillDefinition GetSkillDefinition(string name)
    {
        return new ItemSkillDefinition
        {
            Id = "FlyingCloth_" + name,
            Name = "Skill_" + name,
            Description = "Fly with " + name,
            Icon = new ItemDefinition.Icon(ItemIconType.Large, "Assets/Icons/skills/" + name + ".dds"),
            UnlockLevel = 0
        };
    }
}
