3. Crea un nuevo script en tu proyecto de mod que extienda de `ConanPlayerController`. Añade el siguiente código para permitir la comunicación entre el jugador y el objeto volador:

```csharp
using System;
using Unreal.Core.Meta;
using Unreal.CorePI;
using UnityEngine;
using Conan.Core;

public class FlyableObjectController : ConanPlayerController
{
    private BlueprintSpawnableActor _flyableBlueprintInstance;

    public void SetFlyableInstance(BlueprintSpawnableActor flyableBlueprintInstance)
    {
        _flyableBlueprintInstance = flyableBlueprintInstance;
    }

    public void SetFlyableAsFollowTarget()
    {
        if (_flyableBlueprintInstance == null)
        {
            return;
        }

        var playerControllerComponent =
            FindComponentOnActor<PlayerControllerComponent>(this.gameObject, out int _);
        var flyableComponent =
            FindComponentOnActor<DynamicFlyAIActor>(_flyableBlueprintInstance.gameObject, out _);
        var followTargetComponent =
            FindComponentOnActor<FollowTargetComponent>(this.gameObject, out _);

        followTargetComponent.SetFollowTarget(flyableComponent);
    }

    public void StopFlyableFromFollowing()
    {
        if (_flyableBlueprintInstance == null)
        {
            return;
        }

        var playerControllerComponent =
            FindComponentOnActor<PlayerControllerComponent>(this.gameObject, out int _);
        var followTargetComponent =
            FindComponentOnActor<FollowTargetComponent>(this.gameObject, out _);

        followTargetComponent.ClearFollowTarget();
    }
}
```

