Aquí está la función:

```swift
func gaussJordan(_ augmentedMatrix: [[Double]], scale: Double) -> ([Double], [[Double]]) {
    let n = augmentedMatrix.count // número de ecuaciones
    var matrix = augmentedMatrix // copia de la matriz aumentada

    // rref de la matriz aumentada
    for j in 0 ..< n { // filas
        var maxRow = j
        var maxVal = fabs(matrix[maxRow][j]) // valor más grande en la columna
        for I in (j + 1)..<n { // búsqueda por columna
            if fabs(matrix[i][j]) > maxVal {
                maxRow = I
                maxVal = fabs(matrix[i][j])
            }
        }

        if matrix[maxRow][j] == 0 {
            continue // cambiar de fila si la pivoteo es cero
        }

        if maxRow != j { // intercambiar filas
            var temp = matrix[j]
            matrix[j] = matrix[maxRow]
            matrix[maxRow] = temp
        }

        // normalización de la columna pivoteada
        let factor = 1.0 / matrix[j][j]
        for I in 0..<n+1 { // sumandos en la columna pivoteada
            matrix[j][i] *= factor // dividiendo cada elemento de la fila por el pivote
        }

        for I in 0..<n { // eliminando los sumandos abajo de la fila pivoteada
            if I == j {
                continue
            }

            let mul = matrix[i][j]
            for k in 0..<n+1 { // multiplicando cada elemento de la fila
                matrix[i][k] -= mul * matrix[j][k]
            }
        }
    }

    // solución del sistema
    var solution = [Double](repeating: 0, count: n)
    for I in (0..<n).reversed() {
        let factor = matrix[i][n] / matrix[i][i]
        solution[i] = factor
        for j in 0..<i {
            matrix[i][j] -= factor * matrix[j][i]
        }
    }

    return (solution, matrix)
}
```

