typealias Matrix = [[Double]]
typealias Vector = [Double]

let DoubleFLTolerance: Double = Double.ulpOfOne / 2 // Tolerancia de redondeo

func rationalize(_ ratio: Double, inout _ a: Double) -> Bool {
