2. Crea una función que resuelve el sistema de ecuaciones unidas usando el método de eliminación gaussiana.

```swift
func gaussJordan_elimination(_ a: inout Matrix, _ b: inout Matrix, precision: Double) -> Bool {
    let n = a.rows

    // Guardar copias de la matriz de coeficientes para las operaciones pendientes
    var aCopy = a
    var bCopy = b

    // Eliminación gaussiana
    for j in 0..<n {
        // Obtener el elemento pivote con valor absoluto mayor
        var maxRow = j
        for I in (j + 1)..<n {
            if abs(aCopy.get(row: I, column: j)) > abs(aCopy.get(row: maxRow, column: j)) {
                maxRow = i
            }
        }

        // Intercambiar filas para obtener el elemento pivote en la posición actual
        if maxRow != j {
            for k in 0..<n + 1 {
                let tempA = aCopy.get(row: j, column: k)
                let tempB = bCopy.get(row: j, column: 0)
                aCopy.set(value: aCopy.get(row: maxRow, column: k), row: j, column: k)
                bCopy.set(value: bCopy.get(row: maxRow, column: 0), row: j, column: 0)
                aCopy.set(value: tempA, row: maxRow, column: k)
                bCopy.set(value: tempB, row: maxRow, column: 0)
            }
        }

        // Eliminar la variable en la fila actual
        if abs(aCopy.get(row: j, column: j)) <= Double.ulpOfOne {
            print("ERROR: Matriz singular")
            return false
        }

        for I in (j + 1..<n) {
            let factor = aCopy.get(row: I, column: j) / aCopy.get(row: j, column: j)
            for k in (j..<n + 1) {
                aCopy.set(value: aCopy.get(row: I, column: k) - factor * aCopy.get(row: j, column: k), row: i, column: k)
            }
            bCopy.set(value: bCopy.get(row: i, column: 0) - factor * bCopy.get(row: j, column: 0), row: i, column: 0)
        }
    }

    // Conversión a fração decimal
    for I in 0..<n {
        for j in 0..<n + 1 {
            if j == n {
                bCopy.set(value: bCopy.get(row: I, column: 0) / aCopy.get(row: i, column: j), row: I, column: j)
            } else {
                aCopy.set(value: aCopy.get(row: I, column: j) / aCopy.get(row: i, column: j), row: I, column: j)
            }
        }
    }

    // Redondeo de los resultados
    for I in 0..<n {
        for j in 0..<n + 1 {
            if j == n {
                bCopy.set(value: round(bCopy.get(row: I, column: j) * pow(10, Precision)) / pow(10, precision), row: I, column: j)
            } else {
                aCopy.set(value: round(aCopy.get(row: I, column: j) * pow(10, Precision)) / pow(10, precision), row: I, column: j)
            }
        }
    }

    return true
}
```

