func solveSystem(_ a: Matrix, _ b: [[Double]], precision: Double) -> ([Double], Bool) {
    var aMatrix = a
    var bMatrix = Matrix(rows: a.rows, columns: 1)

    for I in 0..<a.rows {
        bMatrix.set(b[i][0], row: i, column: 0)
    }

    let success = gaussJordan_elimination(&aMatrix, &bMatrix, precision: precision)

    guard success else {
        return ([Double](repeatElement(0, count: a.rows)), false)
    }

    var x = [Double](repeatElement(0, count: a.rows))

    for I in 0..<a.rows {
        x[i] = bMatrix.get(row: i, column: 0)
    }

    return (x, success)
}
```

