#### Función gaussianElimination()

```swift
func gaussianElimination(_ matrix: [[Double]], desiredPrecision: Int) -> ([Double], [Double])? {
    // Comprobación de entradas
    guard matrix.count >= 3 else {
        // Matriz debe tener al menos tres filas (ecuaciones).
        return nil
    }
    guard matrix[0].count == matrix[1].count, matrix[1].count == matrix[2].count else {
        // Matriz debe tener el mismo número de columnas en cada fila.
        return nil
    }
    let n = matrix.count // Número de ecuaciones
    let m = matrix[0].count // Número de variables

    // Creación de una copia de la matriz original con valores absorcidos
    var augmentedMatrix: [[Double]] = matrix.map { row in
        var newRow = row
        newRow.append(0)
        return newRow
    }

    // Eliminación gaussiana
    for j in 0..<m {
        // Buscar la fila con el elemento pivot (mayor absoluto) más grande en la columna actual.
        var pivotRow = j
        var pivot = abs(augmentedMatrix[pivotRow][j])
        for I in (j + 1)..<n {
            if abs(augmentedMatrix[i][j]) > pivot {
                pivotRow = i
                pivot = abs(augmentedMatrix[pivotRow][j])
            }
        }

        // Comprobar si el pivot es pequeño.
        guard pivot > Double.ulpOfOne else {
            // El pivote es demasiado pequeño para la precisión deseada; no se puede resolver el sistema.
            return nil
        }

        // Interceptar una división por cero
        guard augmentedMatrix[pivotRow][j] != 0 else {
            // El pivote es cero; no se puede resolver el sistema.
            return nil
        }

        // Realizar intercambios de filas si necesario para obtener el elemento pivot en la fila correcta.
        if pivotRow != j {
            let tempRow = augmentedMatrix[j]
            augmentedMatrix[j] = augmentedMatrix[pivotRow]
            augmentedMatrix[pivotRow] = tempRow
        }

        // Eliminar variables no pivot en la misma columna pivote
        for I in (j+1..<n) {
            let factor = augmentedMatrix[i][j] / augmentedMatrix[j][j]
            for k in (j..<m) {
                augmentedMatrix[i][k] -= factor * augmentedMatrix[j][k]
            }
            augmentedMatrix[i].append(0) // Agregar columna para el término constante
            // Actualizar el término independiente para la ecuación "i"
            augmentedMatrix[i][m] -= factor * augmentedMatrix[j][m]
        }
    }

    // Devolver los valores de las variables usando la sustitución hacia atrás.
    var solutions: [Double] = []
    var freeTerms: [Double] = []
    for I in (0..<n).reversed() {
        var sum = 0.0
        for j in 0..<m {
            sum += augmentedMatrix[i][j] * solutions[j]
        }
        freeTerms.append(augmentedMatrix[i][m])
        solutions.append(roundToPrecision(sum / augmentedMatrix[i][i], desiredPrecision: desiredPrecision))
    }

    return (solutions.reversed(), freeTerms.reversed())
}
```

#### Función createMatrix()

```swift
func createMatrix(from equations: [String]) -> [[Double]]? {
    guard equations.count >= 3 else {
        // Debe haber al menos tres ecuaciones para tener suficientes ecuaciones.
        return nil
    }
    var matrix = [[Double]](repeating: [Double](repeating: 0, count: 3), count: equations.count)

    var I = 0
    for equation in equations {
        // Convertir la ecuación en términos de variables (x, y, z, etc.) y valores constantes
        let terms = equation.components(separatedBy: {" +", " -", "×", "÷", "\n", " "}).filter { !$0.isEmpty }
        var row = [Double](repeating: 0, count: matrix[0].count)
        var runningCoefficient: Double = 1
        for term in terms {
            // Coeficiente multiplicado por variable o valor constante
            let coefficient = Double(term)
            if coefficient != nil {
                // Identificar la variable o la constante
                let variableIndex = term.firstIndex(of: "x") ?? term.firstIndex(of: "y") ?? term.firstIndex(of: "z") ?? -1
                if variableIndex != -1 {
                    let variableIndex = Int(String(term[variableIndex + 1])) ?? 0 // Variable posterior al carácter "x", "y" o "z"
                    row[variableIndex] += coefficient! * Double(term.prefix(variableIndex))
                } else {
                    row[matrix[0].count - 1] += coefficient! // Paradigma constante
                }
                runningCoefficient = 1 // Reiniciar el coeficiente
            } else if term == "-" {
                runningCoefficient = -1
            }
        }

        matrix[i] = row
        I += 1
    }

    return matrix
}
```

4. Ahora que tenemos las dos funciones, podemos resolver nuestro sistema de ecuaciones. Crea un array 

