const gmailUser = 'YOUR_EMAIL@YOUR_DOMAIN.com';
const serviceKeyJson = PropertiesService.getScriptProperties().getProperty('SERVICE_ACCOUNT_KEY_JSON');

// Cargar las credenciales de servicio para usar en Cloud SQL
const { BigQuery, DataSource, Sql } = require('@google-cloud/sql');
const { BigQuery } = require('@google-cloud/bigquery');
const credentials = {
  projectId: 'YOUR_PROJECT_ID',
  client_email: gmailUser,
  private_key: ServiceAccountCredentials.decrypt(serviceKeyJson, gmailUser).privateKey,
};

// Conectar a tu instancia de Cloud SQL
const options = {
  user: 'root', // El usuario de la instancia de Cloud SQL
  instance: 'INSTANCE_NAME', // El nombre de la instancia de Cloud SQL
  database: 'DATABASE_NAME', // El nombre de la base de datos
  port: 3306, // Puerto de MySQL caso de tu instancia, el puerto puede variar si usaste Postgres o SQL Server
  ssl: true, // Habilitar SSL para una conexión segura
  credentials: {
    client_id: credentials.projectId,
    private_key: credentials.private_key,
    client_email: credentials.client_email,
  },
};

const sqlClient = new Sql(options);

async function insertRow(sqlQuery) {
  try {
    await sqlClient.query({ query: sqlQuery });
    console.log('Se insertó correctamente');
  } catch (error) {
    console.error('Error al insertar en la base de datos:', error);
  }
}

async function selectRows(sqlQuery) {
  try {
    const [rows, ] = await sqlClient.query({ query: sqlQuery });
    console.log('Se recuperaron los datos:', rows);
  } catch (error) {
    console.error('Error al consultar la base de datos:', error);
  }
}

// Ejemplo de uso
insertRow('INSERT INTO mi_tabla (nombre, apellido, edad) VALUES ("John", "Doe", 25)');
selectRows('SELECT * FROM mi_tabla');
```

En el ejemplo anterior, debes reemplazar los valores en negrita por los valores de tu instancia de Cloud SQL:

- `YOUR_EMAIL@YOUR_DOMAIN.com`: Reemplaza con tu correo electrónico de Google Cloud SDK (ejemplo: abc@gmail.com).
- `YOUR_PROJECT_ID`: Reemplaza con el ID de tu proyecto en GCP.
- `INSTANCE_NAME`: Reemplaza con el nombre de la instancia de Cloud SQL que se creó en el paso 2.
- `DATABASE_NAME`: Reemplaza con el nombre de la base de datos a la que desea conectarse en la instancia de Cloud SQL.
- `ServiceAccountCredentials.decrypt(serviceKeyJson, gmailUser).privateKey`: Reemplaza con la clave privada JSON que descargaste del Panel de control de GCP, dentro del recurso de cuenta de servicio (creado en el paso 5).

Así que, después de completar todos estos pasos, debería estar listo para realizar operaciones CRUD en tu instancia de Cloud SQL desde GAS utilizando la API de Cloud SQL. Es importante recordar que proporcionaste tus credenciales de servicio en el paso 5 para que las aplicaciones de GAS puedan conectarse a tu instancia de Cloud SQL. ¡Esperamos que este ejemplo te sea útil!

Para utilizar Google App Script para persistir datos en una base de datos, se puede hacer uso del servicio de Google Cloud Firestore, que es una base de datos NoSQL en tiempo real de Google Cloud Platform.

Aquí se explican los pasos para conectarse a Firestore y realizar operaciones CRUD (Create, Read, Update, Delete) utilizando Google App Script:

**1. Crea una nueva proyecto de Google Cloud Platform y habilita API Firestore v1**

Abre la consola de Google Cloud Platform, crea o selecciona un proyecto y activa el servicio Firebase. Una vez activado, habilita la API Firestore v1 desde la sección "API y servicio" de la interfaz de usuario.

**2. Authentica tu aplicación con Google App Script**

Desde la consola de Google Cloud Platform, haz clic en "Cuentas de servicio" en la barra lateral izquierda y selecciona la cuenta de servicio dentro de la sección "Cuentas de servicio". Crea una nueva cuenta de servicio y proporciónale permisos para el servicio de Firestore.

Luego, desde Google App Script, en el editor de tu proyecto, selecciona la cuenta de servicio para autenticarte con el servicio de Firestore. Para ello, ingresa el siguiente código en el espacio de inicio del proyecto:

```
function getService() {
  const projectId = "<YOUR_PROJECT_ID>";
  const keyFilename = "<PATH_TO_YOUR_SERVICE_ACCOUNT_JSON>";

  const {Firestore} = require("@google-cloud/firestore");
  const firestore = new Firestore({
    projectId,
    keyFilename,
  });

  return firestore;
}
```

Reemplaza `<YOUR_PROJECT_ID>` con el ID de tu proyecto de Google Cloud Platform y `<PATH_TO_YOUR_SERVICE_ACCOUNT_JSON>` con el archivo JSON que obtuviste al crear la cuenta de servicio.

**3. Realiza operaciones CRUD en Firestore**

Ahora que tu aplicación está autenticada con Firestore, puedes usar las operaciones CRUD para interactuar con tu base de datos desde Google App Script.

A continuación se muestran algunos ejemplos:

**3.1 Crear un documento**

```javascript
function createDocument(collectionRef, documentData) {
  const firestore = getService();
  const collection = firestore.collection(collectionRef);

  collection.add(documentData)
    .then((docRef) => {
      console.log(`Document written with ID: ${docRef.id}`);
    })
    .catch((error) => {
      console.error(`Error writing document: ${error}`);
    });
}
```

**3.2 Obtener documentos**

```javascript
function getDocumentsFromCollection(collectionRef) {
  const firestore = getService();
  const collection = firestore.collection(collectionRef);

  collection.get()
    .then((querySnapshot) => {
      if (querySnapshot.size === 0) {
        console.log("No documents found");
      } else {
        querySnapshot.forEach((doc) => {
          console.log(`${doc.id} => ${JSON.stringify(doc.data())}`);
        });
      }
    })
    .catch((error) => {
      console.error(`Error getting documents: ${error}`);
    });
}
```

**3.3 Actualizar un documento**

```javascript
function updateDocument(documentRef, dataToUpdate) {
  const firestore = getService();
  const docRef = firestore.document(documentRef);

  return docRef.update(dataToUpdate);
}
```

**3.4 Eliminar un documento**

```javascript
function deleteDocument(documentRef) {
  const firestore = getService();
  const docRef = firestore.document(documentRef);

  return docRef.delete();
}
```

Estos son solo ejemplos de cómo realizar operaciones CRUD en Firestore desde Google App Script. En tu código, debes usar estos métodos en las funciones específicas de tu aplicación para enlazar con tu base de datos.

Es necesario leer la documentación Oficial de Google para obtener más información sobre Firestore y App Script, ya que la información aquí proporcionada es solo una introducción.

Google App Script (GAS) no permite conectarse directamente a bases de datos externas o cloud-based. Sin embargo, si utiliza Google Cloud Firestore o Google Cloud SQL que son servicios de datos de la plataforma Google, puede utilizar GAS para realizar operaciones CRUD (Create, Read, Update, Delete) en su base de datos.

