```cpp
#include <iostream>
#include <boost/asio.hpp>

int main()
{
    // Crear el servicio de asincronía
    boost::asio::io_context service;

    // Crear el socket de servicio
    boost::asio::tcp::acceptor acceptor(service);

    // Asignar el puerto 8080
    boost::asio::tcp::endpoint endpoint(boost::asio::ip::make_address("0.0.0.0"), 8080);
    acceptor.open(endpoint.protocol());
    acceptor.bind(endpoint);

    // Escuchar solicitudes de conexión
    while (true) {
        boost::asio::tcp::socket socket(service);
        acceptor.accept(socket);

        std::cout << "Nueva conexión: " << socket.remote_endpoint().address().to_string() << ":" << socket.remote_endpoint().port() << std::endl;

        // Aquí puedes leer y escribir datos por medio del socket
    }

    return 0;
}
```

