{
    // Crear socket cliente
    int socketClient = socket(AF_INET, SOCK_STREAM, 0);
    if(socketClient < 0) {
        cerr << "Error al crear el socket cliente" << endl;
        return 1;
    }

    // Agregar información del servidor
    struct sockaddr_in servidorInfo;
    servidorInfo.sin_family = AF_INET;
    servidorInfo.sin_addr.s_addr = inet_addr("192.168.1.100"); // Reemplazar con la IP del servidor a conectarse
    servidorInfo.sin_port = htons(8080); // Reemplazar con el puerto del servidor a conectarse

    // Conectar al servidor
    int conexion = connect(socketClient, (struct sockaddr*) &servidorInfo, sizeof(servidorInfo));
    if (conexion < 0) {
        cerr << "Error conectándose al servidor" << endl;
        return 1;
    }

    // Envía un mensaje al servidor
    const char* mensaje = "Hola, servidor!";
    int enviado = send(socketClient, mensaje, strlen(mensaje), 0);
    if (enviado < 0) {
        cerr << "Error enviando mensaje" << endl;
        close(socketClient);
        return 1;
    }

    // Recibir respuesta del servidor
